import{z as A,x as p,o as l,c as d,q as t,j as E,D as r,d as n,s,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"左偏树与配对堆","description":"","frontmatter":{"title":"左偏树与配对堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/leftist-pairing-heap.md","filePath":"cs/leftist-pairing-heap.md","lastUpdated":1791063341000}'),m={name:"cs/leftist-pairing-heap.md"};function B(c,e,D,h,F,g){const i=p("Mermaid");return l(),d("div",null,[e[2]||(e[2]=t('<h1 id="左偏树与配对堆" tabindex="-1">左偏树与配对堆 <a class="header-anchor" href="#左偏树与配对堆" aria-label="Permalink to &quot;左偏树与配对堆&quot;">​</a></h1><div class="epigraph"><p>堆不必是完全二叉树：左偏用 $npl$ 强迫右脊短，合并沿右脊走；配对堆把合并做成更懒的一对一对。</p><footer>—— 据 Crane, Linear Lists and Priority Queues as Balanced Binary Trees, 1972；Fredman, Sedgewick, Sleator and Tarjan, The Pairing Heap, Algorithmica 1986 整理</footer></div><p><a href="/cs/concurrent-skip-list">上一课</a>是有序字典。优先队列主干若只是数组二叉堆，合并两堆是 \\(\\Theta(n)\\)。<a href="/cs/amortized-analysis">摊还</a> 语言已有。本课不写跳表 CAS。缺口是可合并堆的两个实用成员：左偏堆与配对堆，为后课 Fibonacci / 二项提供对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>meld(H1,H2)</code> 要快。二叉堆数组做不到共享形状。左偏堆：节点有键堆序，再维护 \\(npl\\)（到最近外节点的最短距离），规定左 \\(npl\\ge\\) 右 \\(npl\\)。合并：递归合并右脊与另一堆，再必要时交换左右以恢复左偏。右脊长度 \\(O(\\log n)\\)，故 meld/insert/delete-min 最坏 \\(O(\\log n)\\)。</p><p>配对堆：根的孩子们是无序半堆，delete-min 后把孩子两两配对再沿链收。实现极短；摊还界历史上多轮改进，教学上当「实践快、分析厚」的可并堆。</p><p><span class="marginnote">Crane 的左偏树是早期可并堆。配对堆 Fredman et al. 1986；Iacono 等后续摊还结果，本课不引不存在的编号。</span></p><p><span class="marginnote">「npl（零路径长）」就是从节点走到最近一个空指针所需步数的度量。左偏树要求每个节点左子树的 npl 不小于右子树，这等于把树的质量压向左侧，右侧只留一条短「右脊」——合并正是沿这条脊走，所以脊短则合并快。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>左偏 merge：若一空则返回另一；否则键小的当根，把它的右孩子与另一堆 merge，再 swap 左右若破坏 \\(npl\\)。插入是与单节点 merge。配对：insert 当新根或挂孩子；decrease-key 常割下子树再 merge 回——细节随实现，本课钉「割与 meld」。</p>',10)),(l(),E(o,null,{default:r(()=>[s(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22meld%22%5D%20--%3E%20LFT%5B%22%E5%B7%A6%E5%81%8F%3A%20%E6%B2%BF%E5%8F%B3%E8%84%8A%2C%20%E6%8D%A2%E5%B7%A6%E5%8F%B3%22%5D%0A%20%20M%20--%3E%20PAIR%5B%22%E9%85%8D%E5%AF%B9%3A%20%E4%B8%A4%E4%B8%A4%20merge%20%E5%AD%A9%E5%AD%90%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"与数组堆：可并；索引 decrease-key 要句柄。不要用左偏当排序数组。",-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"左偏的 \\(npl\\) 类似零路径长，保证右脊短，分析干净。配对堆常数小，图算法里常赢 Fibonacci 的理论 \\(O(1)\\) decrease-key——理论与实践分裂从这里开始，下一课 Fibonacci 把 \\(O(1)\\) 摊还减键写清。",-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：\\(npl=0\\) 意味着该节点孩子里有空位。一棵 100 万节点的左偏树，右脊最长约 \\(\\log_2(10^6+1)\\approx 20\\) 层，一次 merge 至多递归 20 步；而数组二叉堆合并两堆要把约 200 万元素重新堆化，差距就在「只走脊、不搬全体」。")],-1)),e[7]||(e[7]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：配对堆 delete-min 后把孩子两两配对再串联，像一群选手两人一组打擂台——第一轮先砍掉一半人数，越往后对手越少。这个「先两两、再顺链」的次序正是摊还分析能压住总代价的关键。")],-1)),(l(),E(o,null,{default:r(()=>[s(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22merge(H1%2C%20H2)%22%5D%20--%3E%20B%7B%22%E6%9F%90%E5%A0%86%E4%B8%BA%E7%A9%BA%EF%BC%9F%22%7D%0A%20%20B%20--%20%22%E6%98%AF%22%20--%3E%20R%5B%22%E8%BF%94%E5%9B%9E%E5%8F%A6%E4%B8%80%E5%A0%86%22%5D%0A%20%20B%20--%20%22%E5%90%A6%22%20--%3E%20C%5B%22%E9%94%AE%E5%B0%8F%E8%80%85%E5%BD%93%E6%A0%B9%20%E9%94%AE%E5%A4%A7%E5%A0%86%E6%8C%82%E5%90%91%E5%85%B6%E5%8F%B3%E5%AD%90%E6%A0%91%22%5D%0A%20%20C%20--%3E%20D%5B%22%E9%80%92%E5%BD%92%20merge(%E6%A0%B9%E7%9A%84%E5%8F%B3%E5%AD%A9%E5%AD%90%2C%20%E9%94%AE%E5%A4%A7%E5%A0%86)%22%5D%0A%20%20D%20--%3E%20E%7B%22%E5%8F%B3%20npl%20%E5%A4%A7%E4%BA%8E%E5%B7%A6%20npl%EF%BC%9F%22%7D%0A%20%20E%20--%20%22%E6%98%AF%22%20--%3E%20F%5B%22%E4%BA%A4%E6%8D%A2%E5%B7%A6%E5%8F%B3%E5%AD%A9%E5%AD%90%E6%81%A2%E5%A4%8D%E5%B7%A6%E5%81%8F%22%5D%0A%20%20E%20--%20%22%E5%90%A6%22%20--%3E%20G%5B%22%E8%BF%94%E5%9B%9E%E6%A0%B9%22%5D%0A%20%20F%20--%3E%20G%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明配对堆的最佳摊还常数。不引入斜堆（skew heap）全文，只承认它是「无 \\(npl\\)、随机或交换」的亲戚。二项堆用明确的秩合并，后两课。</p><p>后课默认：要可并且实现短，左偏或配对。要理论 \\(O(1)\\) 减键，看斐波那契堆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>左偏：npl + 右脊合并，最坏对数 meld。</li><li>配对：实现短，摊还分析更长。</li><li>Fibonacci 堆下一课追 \\(O(1)\\) decrease-key。</li><li>出处：Crane, 1972；Fredman et al., <em>Algorithmica</em>, 1986。</li></ul>',5))])}const T=A(m,[["render",B]]);export{f as __pageData,T as default};
